// gb:gen-sidebar —— 从上游 toc.md 生成 sidebars.js。
//
// 为什么不用 autogenerated + sidebar_position：那要求人工维护 135 个序号，
// 上游每插一页就要重排。而且 introduction/ 的人类标题只存在于 toc.md 里
// （文件名是 lo_9_2_Spreads.md 这种），除了解析它别无来源。
//
// 未翻译的页面按 RED 的决定不出现在侧边栏。生成器同时支持降级成上游英文外链，
// 由 --with-untranslated 开启。
import fs from 'node:fs';
import path from 'node:path';
import {ROOT, UPSTREAM, DOCS, parseToc} from './lib/md.mjs';

const WITH_UNTRANSLATED = process.argv.includes('--with-untranslated');
const LABELS_FILE = path.join(ROOT, 'translation/sidebar-labels.json');
const labels = fs.existsSync(LABELS_FILE) ? JSON.parse(fs.readFileSync(LABELS_FILE, 'utf8')) : {};

const missingLabels = [];
const label = (item) => {
  const zh = labels[item.resolved ?? item.label];
  if (zh) return zh;
  missingLabels.push({key: item.resolved ?? item.label, en: item.label});
  return item.label;
};

// 上游路径一律是 .md，但译文可能是 .mdx —— 需要 Tabs 之类组件的页面只能是 .mdx。
// 这里按两种扩展名依次找，否则那些页会被当成「未翻译」而降级成英文外链。
const resolveDoc = (rel) => {
  if (!/\.mdx?$/.test(rel)) return null; // 目录链接如 `reference/` 也能通过 existsSync
  const stem = rel.replace(/\.mdx?$/, '');
  for (const ext of ['.md', '.mdx']) {
    const abs = path.join(DOCS, stem + ext);
    if (fs.existsSync(abs) && fs.statSync(abs).isFile()) return stem;
  }
  return null;
};
const docExists = (rel) => resolveDoc(rel) !== null;
const docId = (rel) => rel.replace(/\.mdx?$/, '');

// 一文多挂时第二次要降级成 link，而 link 需要一个真实 URL —— 不能拿 docId（文件路径）
// 顶替：本项目每页都有显式 frontmatter slug，文件路径从来就不是有效地址。
// 这个坑一直潜伏着，直到 text-rendering 成为第一个真被挂两次的页面才引爆。
const docUrl = (rel) => {
  const stem = resolveDoc(rel);
  if (!stem) return null;
  for (const ext of ['.md', '.mdx']) {
    const abs = path.join(DOCS, stem + ext);
    if (!fs.existsSync(abs)) continue;
    const m = /^slug:\s*(\S+)\s*$/m.exec(fs.readFileSync(abs, 'utf8'));
    if (m) return m[1];
  }
  return '/' + stem; // 没写 slug 的页才回退到路径
};
const upstreamUrl = (rel) => `https://thegraybook.vvvv.org/${rel.replace(/\.md$/, '.html')}`;

const seenDocs = new Set(); // 一文多挂时，第二次出现降级成 link，避免 prev/next 归属歧义

/** 把 toc 的扁平条目（靠 # 层级）折成树 */
function toTree(items) {
  const root = [];
  const stack = [{depth: 0, children: root}];
  for (const item of items) {
    while (stack.length > 1 && stack[stack.length - 1].depth >= item.depth) stack.pop();
    const node = {item, children: []};
    stack[stack.length - 1].children.push(node);
    stack.push({depth: item.depth, children: node.children});
  }
  return root;
}

/**
 * 展开：目录链接（以 / 结尾）→ 该目录的 toc.md。
 * 子 toc 的层级从 1 重新计数，必须按父级深度整体下移，否则折树时
 * 子章节会和父章节变成兄弟。
 */
function expand(tocRel, depthOffset = 0) {
  const out = [];
  for (const item of parseToc(tocRel)) {
    const depth = item.depth + depthOffset;
    if (item.target.endsWith('/') && item.resolved) {
      const sub = path.posix.join(item.resolved, 'toc.md');
      if (fs.existsSync(path.join(UPSTREAM, sub))) {
        out.push({...item, depth, children: expand(sub, depth)});
        continue;
      }
    }
    out.push({...item, depth});
  }
  return out;
}

function build(nodes) {
  const out = [];
  for (const {item, children} of nodes) {
    const kids = build(children);
    const rel = item.resolved;
    const has = rel && docExists(rel);
    const isDup = has && seenDocs.has(rel);
    if (has && !isDup) seenDocs.add(rel);

    if (kids.length === 0) {
      // 叶子
      if (has && !isDup) out.push({type: 'doc', id: docId(rel), label: label(item)});
      else if (has && isDup) out.push({type: 'link', label: label(item), href: docUrl(rel)});
      else if (WITH_UNTRANSLATED && rel)
        out.push({type: 'link', label: label(item), href: upstreamUrl(rel), className: 'gb-en'});
      continue;
    }
    // 有子项：能落地就带 link，否则纯分组
    const category = {type: 'category', label: label(item), items: kids};
    if (has && !isDup) category.link = {type: 'doc', id: docId(rel)};
    if (kids.length) out.push(category);
  }
  return out;
}

const flatten = (i) => (i.children ? [i, ...i.children.flatMap(flatten)] : [i]);

const countDocs = (items) =>
  items.reduce(
    (n, i) => n + (i.type === 'doc' ? 1 : 0) + (i.items ? countDocs(i.items) : 0) + (i.link ? 1 : 0),
    0,
  );

// 上游目录名与显示名错位：introduction/ 对外叫 Explanations
const sectionKeyOf = (resolved) => {
  const dir = resolved.replace(/\/+$/, '');
  return dir === 'introduction' ? 'explanations' : dir;
};

// 根 toc.md 的四个顶级条目 = 头部四个板块，各出一个具名 sidebar
const sidebars = {};
const sections = [];

for (const rootItem of parseToc('toc.md')) {
  if (!rootItem.resolved) continue;
  const sub = path.posix.join(rootItem.resolved, 'toc.md');
  if (!fs.existsSync(path.join(UPSTREAM, sub))) continue;

  const key = sectionKeyOf(rootItem.resolved);
  const flat = expand(sub).flatMap(flatten);
  const items = build(toTree(flat));
  const docCount = countDocs(items);
  const zh = label(rootItem);

  if (docCount > 0) {
    sidebars[key] = items;
    sections.push({key, label: zh, type: 'docSidebar', sidebarId: key, docCount});
  } else {
    // 整个板块一篇译文都没有 → 头部那一项直接链上游英文，读者不会撞空。
    // 翻到该板块后重新生成即自动转为站内链接，不需要手改 config。
    const first = flat.find((i) => i.resolved && /\.mdx?$/.test(i.resolved));
    sections.push({
      key,
      label: `${zh}（英文）`,
      type: 'link',
      href: first ? upstreamUrl(first.resolved) : `https://thegraybook.vvvv.org/${rootItem.resolved}`,
      docCount: 0,
    });
  }
}

const header = `/**
 * 本文件由 \`npm run gb:gen-sidebar\` 从上游 toc.md 生成，不要手改。
 * 每个上游顶级板块一个具名 sidebar，与头部导航一一对应。
 * 中文标签维护在 translation/sidebar-labels.json，重新生成不会覆盖。
 * 未翻译的页面不出现在这里；要显示为英文外链请加 --with-untranslated。
 */
`;
fs.writeFileSync(
  path.join(ROOT, 'sidebars.js'),
  `${header}module.exports = ${JSON.stringify(sidebars, null, 2)};\n`,
);
fs.writeFileSync(
  path.join(ROOT, 'translation/navbar-sections.json'),
  JSON.stringify(sections, null, 2) + '\n',
);

console.log(`已生成 sidebars.js：${Object.keys(sidebars).length} 个板块`);
for (const s of sections) {
  console.log(
    `  ${s.label.padEnd(14)} ${s.type === 'docSidebar' ? `站内 ${s.docCount} 页` : '→ 上游英文'}`,
  );
}

if (missingLabels.length) {
  const uniq = [...new Map(missingLabels.map((m) => [m.key, m])).values()];
  console.log(`\n缺中文标签 ${uniq.length} 条，请补进 translation/sidebar-labels.json：`);
  uniq.slice(0, 40).forEach((m) => console.log(`  "${m.key}": "",   // ${m.en}`));
  if (uniq.length > 40) console.log(`  …还有 ${uniq.length - 40} 条`);
}
